-- MH-576 D7: one "upgrade all instances" run — rolls every active instance of a product to ref
-- (an image/commit/branch), one at a time with the normal deploy health gate
-- (deploy.Service.QueueDeployment / the release pipeline), so the web UI can show progress.
-- status: running, done, failed (stopped after an instance's deploy failed), cancelled.
CREATE INDEX product_upgrades_product_idx ON product_upgrades (product_id, created_at);
CREATE INDEX product_upgrades_team_idx ON product_upgrades (team_id, created_at);
